SELECT o.*,
l.longitude,
l.latitude
FROM pest_forecast_outcome o
LEFT JOIN pest_light l ON o.light_id = l.device_code


        and o.tenant_id = #{param.tenantId}


        and o.industry_code = #{param.industryCode}


        and o.app_ver_code = #{param.appVerCode}


        and o.pest_type = #{param.pestType}


        and o.light_id = #{param.lightId}


        AND o.create_time BETWEEN #{param.startTime} AND #{param.endTime}


ORDER BY o.create_time DESC;

SELECT o.*,
l.longitude,
l.latitude
FROM (
SELECT *,
ROW_NUMBER() OVER (
PARTITION BY light_id
ORDER BY forecast_date DESC
) AS rn
FROM pest_forecast_outcome


        AND tenant_id = #{param.tenantId}


        AND industry_code = #{param.industryCode}


        AND app_ver_code = #{param.appVerCode}


        AND pest_type = #{param.pestType}


        AND light_id IN

            #{lightId}



        AND create_time BETWEEN #{param.startTime} AND #{param.endTime}


) o
LEFT JOIN pest_light l ON o.light_id = l.device_code
WHERE o.rn = 1
